Tool Arguments: {'additionalProperties': False, 'properties': {'query': {'description': 'Full-text search query.', 'title': 'Query', 'type': 'string'}, 'status': {'anyOf': [{'enum': ['active', 'archived', 'pending', 'deleted'], 'type': 'string'}, {'type': 'null'}], 'default': None, 'description': 'Filter by record status.', 'title': 'Status'}, 'owner_email': {'anyOf': [{'format': 'email', 'type': 'string'}, {'type': 'null'}], 'default': None, 'description': 'Restrict to records owned by this email address.', 'title': 'Owner Email'}, 'created_after': {'anyOf': [{'format': 'date-time', 'type': 'string'}, {'type': 'null'}], 'default': None, 'description': 'Only records created at or after this RFC 3339 timestamp.', 'title': 'Created After'}, 'limit': {'anyOf': [{'maximum': 100, 'minimum': 1, 'type': 'integer'}, {'type': 'null'}], 'default': 20, 'description': 'Maximum number of records to return.', 'title': 'Limit'}}, 'required': ['query'], 'title': 'DynamicModel', 'type': 'object'}
